import { useState, useEffect } from 'react';
import type { CSSProperties } from 'react';
import { Document, Page, pdfjs } from 'react-pdf';
import type { BmpRecord } from '../data/bmps.ts';
// Generated by scripts/extract_checklist_fields.mjs; rerun it if the PDF changes
import checklistFields from '../data/checklistFields.json';
import { buildFilledPdf } from './filledChecklist.ts';
import { apiFetch } from '../auth.ts';

import "react-pdf/dist/Page/AnnotationLayer.css";
import "react-pdf/dist/Page/TextLayer.css"
// Legacy build polyfills newer JS (e.g. Uint8Array.toHex) missing in some browsers
import workerUrl from "pdfjs-dist/legacy/build/pdf.worker.min.mjs?url";

export type OverlayField = {
  id: string;
  page: number;                     // 0-based
  type: 'text' | 'textarea' | 'checkbox' | 'radio';
  label: string;                    // nearby PDF text, e.g. "Project/BMP Name"
  group?: string;                   // radio group, e.g. "p1-BMP Type:"
  left: number; top: number;        // scale-1 px from the page's top-left
  width: number; height: number;
};

pdfjs.GlobalWorkerOptions.workerSrc = workerUrl;

const FIELDS = checklistFields as OverlayField[];

const isoDate = (v?: string) => (v && /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : '');
const todayIso = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
// Header text fields prefilled from the GIS data, by label (every checklist has the same header).
// The name and in-service date come from the master list: the geodatabase has no fields for them.
const PREFILL: Record<string, (r: BmpRecord) => string | undefined> = {
  'Project/BMP Name': r => r.name,
  'Plan/BMP # if applicable': r => r.sfNumber,
  'Date BMP Placed into Service': r => isoDate(r.mdeClosure),
  'Date of Inspection': () => todayIso(),
};

// Text fields hold strings, checkboxes booleans, radio groups the id of the chosen option
export type Values = Record<string, string | boolean>;

type Props = { file: string; data: BmpRecord | null; scale?: number };

const submitButton: CSSProperties = {
  position: "fixed",
  bottom: "30px",
  right: "30px",
  zIndex: 10000,
  padding: "12px 20px",
  borderRadius: "8px",
  border: "none",
  backgroundColor: "#000",
  color: "#f7cc0d",
  cursor: "pointer",
};

class SessionExpiredError extends Error {}

// btoa needs a binary string; build it in chunks so large PDFs don't overflow the call stack
function toBase64(bytes: Uint8Array) {
  let binary = '';
  for (let i = 0; i < bytes.length; i += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(binary);
}

// The backend forwards the PDF to the Google Drive folder and returns the file's link
async function uploadReport(pdf: Uint8Array, filename: string, bmp: BmpRecord | null): Promise<string> {
  const res = await apiFetch('/reports', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    // The BMP goes along so the work order it opens says what was inspected
    body: JSON.stringify({ filename, pdf: toBase64(pdf), bmp_id: bmp?.trackingNumber, bmp_name: bmp?.name }),
  });
  if (res.status === 401) throw new SessionExpiredError('Your session has expired.');
  const body = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(typeof body.detail === 'string' ? body.detail : 'Could not save the report');
  return body.drive_url;
}

export default function PdfViewer({ file, data, scale = 1.25 }: Props) {
  const [numPages, setNumPages] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [values, setValues ] = useState<Values>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [sessionExpired, setSessionExpired] = useState(false);
  const [submittedUrl, setSubmittedUrl] = useState<string | null>(null);
  useEffect(() => {
    if (!data) return;
    const initial: Values = {};
    for (const f of FIELDS) {
      const fill = f.type === 'text' ? PREFILL[f.label]?.(data) : undefined;
      if (fill) initial[f.id] = String(fill);
    }
    setValues(initial);
  }, [data]);

  const set = (key: string, value: string | boolean) => setValues(v => ({ ...v, [key]: value }));

  const handleSubmit = async () => {
    setSubmitting(true);   // also blocks a double-click from sending two reports
    setSubmitError(null);
    setSessionExpired(false);
    setSubmittedUrl(null);
    try {
      const pdf = await buildFilledPdf(file, FIELDS, values);
      setSubmittedUrl(await uploadReport(pdf, `${data?.trackingNumber ?? 'report'}_${todayIso()}.pdf`, data));
    } catch (err) {
      setSessionExpired(err instanceof SessionExpiredError);
      setSubmitError(err instanceof Error ? err.message : 'Could not create the report');
    } finally {
      setSubmitting(false);
    }
  };

  const renderField = (f: OverlayField) => {
    const box: CSSProperties = {
      position: 'absolute',
      left: f.left * scale,
      top: f.top * scale,
      width: f.width * scale,
      height: f.height * scale,
      margin: 0,
      boxSizing: 'border-box',
      zIndex: 3,                    // above the canvas
    };
    const textStyle: CSSProperties = {
      ...box,
      fontSize: Math.min(10, f.height * 0.75) * scale,
      padding: `0 ${2 * scale}px`,
      border: 'none',
      background: 'rgba(0, 112, 175, 0.12)',
    };
    switch (f.type) {
      case 'checkbox':
        return <input key={f.id} type="checkbox" title={f.label} style={box}
          checked={values[f.id] === true} onChange={e => set(f.id, e.target.checked)} />;
      case 'radio':
        return <input key={f.id} type="radio" title={f.label} style={box} name={f.group}
          checked={values[f.group!] === f.id} onChange={() => set(f.group!, f.id)} />;
      case 'textarea':
        return <textarea key={f.id} title={f.label} style={{ ...textStyle, resize: 'none', lineHeight: 1.2 }}
          value={String(values[f.id] ?? '')} onChange={e => set(f.id, e.target.value)} />;
      default:
        return <input key={f.id} title={f.label} style={textStyle}
          value={String(values[f.id] ?? '')} onChange={e => set(f.id, e.target.value)} />;
    }
  };

  return (
    <div 
      style={{
        width: "80%",
      }}
    >
      {error && <p>{error}</p>}
      <Document
        file={file}
        onLoadSuccess={({numPages}) => {
          setNumPages(numPages);
          setError(null);
        }}
        onLoadError={(err) => {
          setError(err.message);
        }}
        loading={<p>Loading PDF...</p>}
      >
        {Array.from({ length: numPages }, (_, i) => (
          <Page
            key={i}
            pageNumber={i + 1}
            scale={scale}
            renderTextLayer={false}        // otherwise these layers can steal clicks
            renderAnnotationLayer={false}
          >
            {FIELDS.filter(f => f.page === i).map(renderField)}
          </Page>
        ))}
      </Document>
      {numPages > 0 && (
        <button
          style={{ ...submitButton, ...(submitting ? { opacity: 0.6, cursor: 'wait' } : {}) }}
          disabled={submitting}
          onClick={handleSubmit}
        >
          {submitting ? 'Submitting...' : 'Submit report'}
        </button>
      )}
      {submitError && (
        <p style={{ position: 'fixed', bottom: '80px', right: '30px', zIndex: 10000, margin: 0,
                    padding: '8px 12px', borderRadius: '8px', background: '#fff', color: 'red' }}>
          {submitError}
          {/* Logging in from another tab updates this one, so the answers here survive */}
          {sessionExpired && <> <a href="/login" target="_blank" rel="noreferrer">Log in again</a> in a new tab, then submit. Your answers are kept.</>}
        </p>
      )}
      {submittedUrl && (
        <p style={{ position: 'fixed', bottom: '80px', right: '30px', zIndex: 10000, margin: 0,
                    padding: '8px 12px', borderRadius: '8px', background: '#fff', color: 'green' }}>
          Report submitted. <a href={submittedUrl} target="_blank" rel="noreferrer">View in Google Drive</a>
        </p>
      )}
    </div>
  )
}
